{
  "status": "SUPPORTED",
  "task_summary": "Locate fastening parts, assemble them at the workbench, and store the tool.",
  "task_contract": {
    "functional_roles": [
      {
        "id": "target_location",
        "entity_kind": "REGION",
        "function": "The specific area on the workbench where the fastening must occur.",
        "required_count": 1,
        "binding_policy": "SHARED"
      ,
        "candidate_categories": [
          "workbench_surface",
          "table_top"
        ],
        "required_properties": [
          "flat",
          "wooden"
        ]
      },
      {
        "id": "fastening_component",
        "entity_kind": "OBJECT",
        "function": "A physical part needed to secure the target.",
        "required_count": 1,
        "binding_policy": "DISTINCT"
      ,
        "candidate_categories": [
          "screw",
          "bolt",
          "peg",
          "clip"
        ],
        "required_properties": [
          "compatible",
          "rigid"
        ]
      },
      {
        "id": "fastening_tool",
        "entity_kind": "OBJECT",
        "function": "An implement used to perform the fastening action.",
        "required_count": 1,
        "binding_policy": "REUSABLE"
      ,
        "candidate_categories": [
          "screwdriver",
          "glue_bottle",
          "hammer"
        ],
        "required_properties": [
          "functional"
        ]
      }
    ],
    "functional_relations": [
      {
        "id": "requires_component",
        "relation": "DEPENDS_ON",
        "participant_roles": [
          "target_location",
          "fastening_component"
        ]
      ,
        "required": true
      },
      {
        "id": "used_by",
        "relation": "USES",
        "participant_roles": [
          "fastening_tool",
          "fastening_component"
        ]
      ,
        "required": true
      },
      {
        "id": "stored_at",
        "relation": "LOCATED_AT",
        "participant_roles": [
          "fastening_tool",
          "target_location"
        ]
      ,
        "required": true
      }
    ],
    "operation_pairings": [
      {
        "id": "search_and_select",
        "operation": "IDENTIFY_AND_SELECT",
        "participant_roles": [
          "fastening_tool",
          "fastening_component"
        ]
      ,
        "operation_count": 1
      },
      {
        "id": "assemble",
        "operation": "FASTEN",
        "participant_roles": [
          "fastening_component",
          "target_location",
          "fastening_tool"
        ]
      ,
        "operation_count": 1
      },
      {
        "id": "cleanup",
        "operation": "PLACE_SAFE",
        "participant_roles": [
          "fastening_tool",
          "target_location"
        ]
      ,
        "operation_count": 1
      }
    ]
  },
  "observation_guidance": {
    "visible_candidates_per_role": {
      "target_location": [
        {
          "label": "wooden_table_top",
          "visual_description": "A wooden surface with a black tray holding a yellow object."
        }
      ],
      "fastening_component": [],
      "fastening_tool": []
    },
    "inspectable_regions": [
      {
        "id": "blue_cabinet",
        "label": "Cabinet",
        "visual_description": "A tall blue cabinet with a handle.",
        "reason": "Could contain tools or components."
      },
      {
        "id": "left_drawer",
        "label": "Drawer",
        "visual_description": "A blue drawer under the left side of the table.",
        "reason": "Could contain tools or components."
      },
      {
        "id": "right_drawer",
        "label": "Drawer",
        "visual_description": "A blue drawer under the right side of the table.",
        "reason": "Could contain tools or components."
      },
      {
        "id": "black_tray",
        "label": "Tray",
        "visual_description": "A black tray on the table holding a yellow object.",
        "reason": "May contain the fastening components."
      }
    ],
    "inspection_order": [
      "black_tray",
      "left_drawer",
      "right_drawer",
      "blue_cabinet"
    ]
  }
  ,
  "unsupported_reason": ""
  ,
  "schema_version": 3
}
